import sys; sys.path.insert(0, str(WORK))
from cvlib import *
R = np.load(WORK/'base_reads.npz'); y=R['y']; res=np.load(WORK/'reserved.npy')
keep = np.setdiff1d(np.arange(768), res)
M = lambda L: R[f'mean_hidden_L{L}'][:,keep]
C = lambda L: R[f'cls_hidden_L{L}'][:,keep]
Y=np.eye(8)[y]
def nz(X):
    Z=(X-X.mean(0))/(X.std(0)+1e-6); return Z/np.linalg.norm(Z,axis=1,keepdims=True)
def kern_cv_blocks(blocks, kfun, lams, seeds=(0,1,2)):
    Cs=[nz(B)@nz(B).T for B in blocks]; Cm=sum(Cs)/len(Cs)
    K=kfun(Cm); out={l:[] for l in lams}
    for s in seeds:
        f=folds(y,5,s); S={l:np.zeros((len(y),8)) for l in lams}
        for i in range(5):
            tr=f!=i; te=f==i
            for l in lams:
                A=np.linalg.solve(K[np.ix_(tr,tr)]+l*np.eye(tr.sum()), Y[tr]-Y[tr].mean(0)); S[l][te]=K[np.ix_(te,tr)]@A
        for l in lams: out[l].append((S[l].argmax(1)==y).mean())
    return {l:round(float(np.mean(v)),4) for l,v in out.items()}
q=lambda Cm: Cm+0.5*Cm**2
e=lambda Cm: np.exp(0.8*(Cm-1))
for name, bl in [('M1',[M(1)]),('M0',[M(0)]),('M2',[M(2)]),('M0M1',[M(0),M(1)]),('M1C1',[M(1),C(1)]),('M1M2',[M(1),M(2)]),('M1M2C2',[M(1),M(2),C(2)]),('M0-3',[M(0),M(1),M(2),M(3)]),('M1M9',[M(1),M(9)])]:
    print(name, 'quad', kern_cv_blocks(bl,q,[1e-3,1e-2]), 'exp', kern_cv_blocks(bl,e,[1e-3,1e-2]))
